//! `checkers` against the real nav2_controller plugins (tests/data/checkers.json,
//! regenerated by tests/oracle/run_oracle.sh checkers), and the yaml they
//! are configured from.

mod common;

use common::{assert_close, f};
use mower_nav_core::checkers::{
    SimpleGoalChecker, SimpleGoalCheckerParams, SimpleProgressChecker, SimpleProgressCheckerParams,
};
use mower_nav_core::geometry::{yaw_from_quaternion, Pose2D, Twist2D};
use serde_json::Value;

/// `common::load`, but with every float read correctly rounded. serde_json
/// without its `float_roundtrip` feature reads about one float in ten of
/// these files one ulp off, which flips boundary cases (the xy tolerance
/// circle); serde_yaml parses JSON (it is YAML) with `str::parse::<f64>`.
fn load_exact(name: &str) -> Value {
    let path = format!("{}/tests/data/{}", env!("CARGO_MANIFEST_DIR"), name);
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("cannot read {path}: {e} (run tests/oracle/run_oracle.sh)"));
    serde_yaml::from_str(&text).unwrap_or_else(|e| panic!("cannot parse {path}: {e}"))
}

/// `[x, y, qz, qw]` of a `setRPY(0, 0, yaw)` pose, read the way the IO
/// layer reads a `geometry_msgs/Pose`.
fn pose(v: &[Value]) -> Pose2D {
    Pose2D::new(f(&v[0]), f(&v[1]), yaw_from_quaternion(0.0, 0.0, f(&v[2]), f(&v[3])))
}

fn b(v: &Value) -> bool {
    v.as_bool().unwrap_or_else(|| panic!("bool expected, got {v}"))
}

fn goal_params(v: &Value) -> SimpleGoalCheckerParams {
    SimpleGoalCheckerParams {
        xy_goal_tolerance: f(&v["xy_goal_tolerance"]),
        yaw_goal_tolerance: f(&v["yaw_goal_tolerance"]),
        stateful: b(&v["stateful"]),
        symmetric_yaw_tolerance: b(&v["symmetric_yaw_tolerance"]),
    }
}

fn progress_params(v: &Value) -> SimpleProgressCheckerParams {
    SimpleProgressCheckerParams {
        required_movement_radius: f(&v["required_movement_radius"]),
        movement_time_allowance: f(&v["movement_time_allowance"]),
    }
}

fn assert_all_close(ours: &[f64], theirs: &Value, what: &str) {
    let theirs = theirs.as_array().unwrap();
    assert_eq!(ours.len(), theirs.len(), "{what}");
    for (a, e) in ours.iter().zip(theirs) {
        assert_close(*a, f(e), what);
    }
}

#[test]
fn oracle_configurations_are_the_defaults_and_the_yaml() {
    let d = load_exact("checkers.json");
    let goal = |name: &str| {
        let c = d["goal_checker"].as_array().unwrap().iter().find(|c| c["name"] == name).unwrap();
        goal_params(&c["params"])
    };
    assert_eq!(goal("general_goal_checker"), SimpleGoalCheckerParams::mower());
    assert_eq!(goal("default_goal_checker"), SimpleGoalCheckerParams::default());
    let progress = |name: &str| {
        let c = d["progress_checker"].as_array().unwrap().iter().find(|c| c["name"] == name).unwrap();
        progress_params(&c["params"])
    };
    assert_eq!(progress("progress_checker"), SimpleProgressCheckerParams::mower());
    assert_eq!(progress("default_progress_checker"), SimpleProgressCheckerParams::default());
}

#[test]
fn goal_checker_matches_simple_goal_checker() {
    let d = load_exact("checkers.json");
    for c in d["goal_checker"].as_array().unwrap() {
        let name = c["name"].as_str().unwrap();
        let mut checker = SimpleGoalChecker::new(goal_params(&c["params"]));
        let mut goal = Pose2D::default();
        let (mut calls, mut reached) = (0, 0);
        for (i, op) in c["ops"].as_array().unwrap().iter().enumerate() {
            let op = op.as_array().unwrap();
            let what = format!("{name} op {i} {op:?}");
            match op[0].as_str().unwrap() {
                "goal" => goal = pose(&op[1..5]),
                "reached" => {
                    let velocity = Twist2D::new(f(&op[5]), 0.0, f(&op[6]));
                    let r = checker.is_goal_reached(&pose(&op[1..5]), &goal, &velocity);
                    assert_eq!(r, b(&op[7]), "{what}: result");
                    assert_eq!(checker.checks_xy(), b(&op[8]), "{what}: check_xy");
                    calls += 1;
                    reached += r as usize;
                }
                "reset" => {
                    checker.reset();
                    assert_eq!(checker.checks_xy(), b(&op[1]), "{what}: check_xy");
                }
                "tolerances" => {
                    assert!(b(&op[1]));
                    let t = checker.get_tolerances();
                    assert_all_close(&t.position, &op[2], &format!("{what}: position"));
                    assert_all_close(&t.orientation, &op[3], &format!("{what}: orientation"));
                    assert_all_close(&t.linear, &op[4], &format!("{what}: linear"));
                    assert_all_close(&t.angular, &op[5], &format!("{what}: angular"));
                }
                other => panic!("unknown op {other}"),
            }
        }
        assert!(calls > 900 && reached > 300 && calls - reached > 300, "{name}: {reached}/{calls}");
    }
}

#[test]
fn progress_checker_matches_simple_progress_checker() {
    let d = load_exact("checkers.json");
    for c in d["progress_checker"].as_array().unwrap() {
        let name = c["name"].as_str().unwrap();
        let mut checker = SimpleProgressChecker::new(progress_params(&c["params"]));
        let mut failed = 0;
        for (i, op) in c["ops"].as_array().unwrap().iter().enumerate() {
            let op = op.as_array().unwrap();
            match op[0].as_str().unwrap() {
                "check" => {
                    let t = op[1].as_i64().unwrap();
                    let r = checker.check(&Pose2D::new(f(&op[2]), f(&op[3]), 0.0), t);
                    assert_eq!(r, b(&op[4]), "{name} op {i} {op:?}");
                    failed += !r as usize;
                }
                "reset" => checker.reset(),
                other => panic!("unknown op {other}"),
            }
        }
        assert!(failed > 100, "{name}: only {failed} failed checks");
    }
}

fn production_yaml() -> serde_yaml::Value {
    let path = format!("{}/../../../mower_nav2/config/nav2_no_map_params.yaml", env!("CARGO_MANIFEST_DIR"));
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{path}: {e}"));
    serde_yaml::from_str(&text).unwrap_or_else(|e| panic!("{path}: {e}"))
}

/// The yaml still says what `mower()` says (the oracle vectors were made
/// from it, so a change there needs both regenerated).
#[test]
fn mower_params_match_the_yaml() {
    let y = production_yaml();
    let cs = &y["controller_server"]["ros__parameters"];
    assert_eq!(cs["goal_checker_plugins"][0].as_str(), Some("general_goal_checker"));
    assert_eq!(cs["progress_checker_plugins"][0].as_str(), Some("progress_checker"));
    let g = &cs["general_goal_checker"];
    assert_eq!(g["plugin"].as_str(), Some("nav2_controller::SimpleGoalChecker"));
    let p = SimpleGoalCheckerParams::mower();
    assert_eq!(g["xy_goal_tolerance"].as_f64(), Some(p.xy_goal_tolerance));
    assert_eq!(g["yaw_goal_tolerance"].as_f64(), Some(p.yaw_goal_tolerance));
    assert_eq!(g["stateful"].as_bool(), Some(p.stateful));
    assert!(g.get("symmetric_yaw_tolerance").is_none());
    let pc = &cs["progress_checker"];
    assert_eq!(pc["plugin"].as_str(), Some("nav2_controller::SimpleProgressChecker"));
    let p = SimpleProgressCheckerParams::mower();
    assert_eq!(pc["required_movement_radius"].as_f64(), Some(p.required_movement_radius));
    assert_eq!(pc["movement_time_allowance"].as_f64(), Some(p.movement_time_allowance));
}
